import{_ as i,o as e,a,b as d}from"./app.DKoEZOcr.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{"breadcrumbs":[{"text":"Ascend C算子开发指南","link":"/guide/getting_started/ascend_c_overview_and_learning_path"},{"text":"编程指南","link":"/guide/programming_guide/document_structure"},{"text":"编译与运行","link":"/guide/programming_guide/compilation_and_execution/compilation_and_execution"},{"text":"算子编译","link":"/guide/programming_guide/compilation_and_execution/operator_compilation/bisheng_compiler"},{"text":"毕昇编译器","link":"/guide/programming_guide/compilation_and_execution/operator_compilation/bisheng_compiler"}]},"headers":[],"relativePath":"guide/programming_guide/compilation_and_execution/operator_compilation/bisheng_compiler.md","filePath":"guide/programming_guide/compilation_and_execution/operator_compilation/bisheng_compiler.md","lastUpdated":1786949923000}'),o={name:"guide/programming_guide/compilation_and_execution/operator_compilation/bisheng_compiler.md"};function n(r,t,l,c,_,p){return e(),a("div",null,[...t[0]||(t[0]=[d('<div><article class="markdown-body"><h1>毕昇编译器简介<span id="ZH-CN_TOPIC_0000002457558450"></span></h1><p>毕昇编译器是专为昇腾AI处理器设计的异构编译器，原生支持Ascend C算子代码的编译，可将用户编写的算子程序高效转换为二进制可执行文件或动态库。编译器的可执行文件名为bisheng，支持x86、aarch64等多种主机平台，并直接提供对设备侧AI Core架构的指令集编译支持。借助毕昇编译器，开发者可以更高效、便捷地完成面向昇腾平台的算子开发与优化工作。</p><p>目前，编译器支持如下型号：</p><div data-filter="950"><ul><li>Ascend 950PR/Ascend 950DT</li></ul></div><div data-filter="A3"><ul><li>Atlas A3 训练系列产品/Atlas A3 推理系列产品</li></ul></div><div data-filter="910b"><ul><li>Atlas A2 训练系列产品/Atlas A2 推理系列产品</li></ul></div><div data-filter="310p"><ul><li>Atlas 推理系列产品</li></ul></div><p>毕昇编译器支持的源码文件核头文件如下：</p><table><thead><tr><th>文件扩展名</th><th>描述</th><th>内容</th></tr></thead><tbody><tr><td>.c</td><td>C源码文件</td><td>Host-only代码</td></tr><tr><td>.cpp, .cc, .cxx</td><td>C++源码文件</td><td>Host-only代码</td></tr><tr><td>.h, .hpp, .hh, .hxx</td><td>C/C++头文件</td><td>Device代码， Host代码， Host/Device混合代码</td></tr><tr><td>.asc</td><td>Ascend C源码文件</td><td>Device代码， Host代码， Host/Device混合代码</td></tr></tbody></table><ul><li>异构编译场景中的编程相关约束请参考<a href="constraints.html">约束说明</a>。</li><li>如果需要了解更多的毕昇编译器的基础知识，详细内容请参考<a href="https://www.hiascend.com/document/redirect/CannCommunityBiSheng">《毕昇编译器用户指南》</a>。</li></ul></article></div>',1)])])}const u=i(o,[["render",n]]);export{m as __pageData,u as default};
